29	// It applies the built-in block rules to one transaction, so its conclusion
30	// matches DetectBlock for the same records: neighbours are the adjacent
31	// swaps inside the victim's own pool ordered by Index, never swaps from
32	// other pools and never positions in the input slice. Reordering the input
33	// or interleaving other pools therefore cannot change the result. The
34	// victim's pool's last swap is still checked for displacement against its
35	// predecessor; a victim that is absent or first in its pool has no
36	// conclusion. The passed slice is never modified.
37	func Detect(swaps []Swap, victim string) []Finding {
38		// Single-transaction detection always runs the built-in version:
39		// sandwich severity 3, displacement severity 2 with multiplier 2.
40		rules := BuiltinVersion().Rules
41		target, ok := findSwap(swaps, victim)
42		if !ok {
43			return nil
44		}
45		pool := poolSwaps(swaps, target.Pool)
46		pos := -1
47		for i, s := range pool {
48			if s.TxHash == victim {
49				pos = i
50				break
51			}
52		}
53		var front, back *Swap
54		if pos > 0 {
55			front = &pool[pos-1]
56		}
57		if pos >= 0 && pos+1 < len(pool) {
58			back = &pool[pos+1]
59		}
60		j, hit := judgeVictim(front, target, back, rules)
61		if !hit {
62			return nil
63		}
64		if j.kind == "sandwich" {
65			return []Finding{{
66				TxHash: victim, Kind: j.kind, Severity: j.severity,
67				Evidence: []string{
68					"front-run by " + front.Trader + " at gas " + strconv.FormatInt(front.GasPrice, 10),
69					"back-run by " + back.Trader + " at gas " + strconv.FormatInt(back.GasPrice, 10),
70					"victim gas " + strconv.FormatInt(target.GasPrice, 10),
71				},
72			}}
73		}
74		return []Finding{{TxHash: victim, Kind: j.kind, Severity: j.severity,
75			Evidence: []string{"front gas dominates victim by more than 2x"}}}
76	}
