1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"syscall"
14	)
15	
16	// Block is one validated, deduplicated input block. Swaps are kept in
17	// canonical order: exact duplicates removed, sorted by Index.
18	type Block struct {
19		ChainID     string
20		BlockHash   string
21		BlockNumber int64
22		Swaps       []Swap
23	}
24	
25	// ReportFinding is one risk conclusion inside a block report. Evidence
26	// carries the raw fields of every swap that participated in the judgment.
27	type ReportFinding struct {
28		Kind     string `json:"kind"`
29		Severity int    `json:"severity"`
30		TxHash   string `json:"txHash"`
31		Evidence []Swap `json:"evidence"`
32	}
33	
34	// Report is the archived per-block risk report. Version records the full
35	// rule parameters that produced the findings, so the report stays
36	// interpretable without the original rule definition.
37	type Report struct {
38		ChainID     string          `json:"chainId"`
39		BlockHash   string          `json:"blockHash"`
40		BlockNumber int64           `json:"blockNumber"`
41		SwapCount   int             `json:"swapCount"`
42		Version     RuleVersion     `json:"version"`
43		Findings    []ReportFinding `json:"findings"`
44	}
45	
46	// LineError pins a replay failure to a 1-based input line.
47	type LineError struct {
48		Line int
49		Err  error
50	}
51	
52	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
53	func (e *LineError) Unwrap() error { return e.Err }
54	
55	// ErrBusy reports an archive locked by another process.
56	var ErrBusy = errors.New("archive is busy")
57	
58	// ErrUnknownBlock reports a query for a block that was never archived.
59	var ErrUnknownBlock = errors.New("unknown block")
60	
61	type blockID struct {
62		chainID   string
63		blockHash string
64	}
65	
66	// blockLine mirrors one input line. Pointers distinguish a missing field
67	// from an explicit zero value.
68	type blockLine struct {
69		ChainID     *string `json:"chainId"`
70		BlockHash   *string `json:"blockHash"`
71		BlockNumber *int64  `json:"blockNumber"`
72		Swaps       *[]Swap `json:"swaps"`
73	}
74	
75	func parseBlock(text string) (Block, error) {
76		var raw blockLine
77		dec := json.NewDecoder(strings.NewReader(text))
78		if err := dec.Decode(&raw); err != nil {
79			return Block{}, fmt.Errorf("invalid JSON: %w", err)
80		}
81		if dec.More() {
82			return Block{}, errors.New("invalid JSON: unexpected trailing data")
83		}
84		if raw.ChainID == nil || *raw.ChainID == "" {
85			return Block{}, errors.New("chainId must be a non-empty string")
86		}
87		if raw.BlockHash == nil || *raw.BlockHash == "" {
88			return Block{}, errors.New("blockHash must be a non-empty string")
89		}
90		if raw.BlockNumber == nil {
91			return Block{}, errors.New("blockNumber is required")
92		}
93		if *raw.BlockNumber < 0 {
94			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
95		}
96		if raw.Swaps == nil {
97			return Block{}, errors.New("swaps must be an array")
98		}
99	
100		byTx := make(map[string]Swap)
101		byIndex := make(map[int]string)
102		swaps := []Swap{}
103		for i, s := range *raw.Swaps {
104			if s.TxHash == "" {
105				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
106			}
107			if s.Pool == "" {
108				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
109			}
110			if s.Trader == "" {
111				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
112			}
113			if s.In < 0 || s.Out < 0 || s.GasPrice < 0 || s.Index < 0 {
114				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
115			}
116			if prev, ok := byTx[s.TxHash]; ok {
117				if prev != s {
118					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, s.TxHash)
119				}
120				continue // exact duplicate, keep one copy
121			}
122			if other, ok := byIndex[s.Index]; ok {
123				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, s.Index, other)
124			}
125			byTx[s.TxHash] = s
126			byIndex[s.Index] = s.TxHash
127			swaps = append(swaps, s)
128		}
129		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
130		return Block{
131			ChainID:     *raw.ChainID,
132			BlockHash:   *raw.BlockHash,
133			BlockNumber: *raw.BlockNumber,
134			Swaps:       swaps,
135		}, nil
136	}
137	
138	func swapsEqual(a, b []Swap) bool {
139		if len(a) != len(b) {
140			return false
141		}
142		for i := range a {
143			if a[i] != b[i] {
144				return false
145			}
146		}
147		return true
148	}
149	
150	// sameContent reports whether two blocks carry the same content. Both sides
151	// are canonical (deduplicated, sorted by Index), so ordering and exact
152	// duplicates in the input do not affect the comparison.
153	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
154		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
155	}
156	
157	// DetectBlock checks every swap against its adjacent neighbours within its
158	// pool under the built-in rules. See DetectBlockWithRules.
159	func DetectBlock(swaps []Swap) []ReportFinding {
160		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
161	}
162	
163	// DetectBlockWithRules checks every swap against its adjacent neighbours
164	// within its pool under the given rule version: a sandwich when the same
165	// trader brackets the victim with higher gas on both sides, otherwise a
166	// displacement when the previous swap's gas strictly exceeds the configured
167	// multiple of the victim's. The last swap of a pool is checked too. An
168	// enabled sandwich takes priority over displacement for the same victim;
169	// with the sandwich rule off the victim can still be flagged for
170	// displacement. With both rules off the result is an empty slice. The
171	// judgment itself is shared with Detect; this entry only adds the block
172	// report's raw-swap evidence and ordering.
173	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
174		pools := make(map[string][]Swap)
175		for _, s := range swaps {
176			pools[s.Pool] = append(pools[s.Pool], s)
177		}
178		findings := []ReportFinding{}
179		for _, pool := range pools {
180			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
181			for i, victim := range pool {
182				var front, back *Swap
183				if i > 0 {
184					front = &pool[i-1]
185				}
186				if i+1 < len(pool) {
187					back = &pool[i+1]
188				}
189				j, hit := judgeVictim(front, victim, back, rules)
190				if !hit {
191					continue
192				}
193				// The evidence keeps the full swap fields of every record that
194				// participated: front, victim, and for a sandwich also back.
195				evidence := []Swap{*front, victim}
196				if j.kind == "sandwich" {
197					evidence = append(evidence, *back)
198				}
199				findings = append(findings, ReportFinding{
200					Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
201					Evidence: evidence,
202				})
203			}
204		}
205		sort.Slice(findings, func(i, j int) bool {
206			if findings[i].Severity != findings[j].Severity {
207				return findings[i].Severity > findings[j].Severity
208			}
209			return findings[i].TxHash < findings[j].TxHash
210		})
211		return findings
212	}
213	
214	// record is the archived form of a block: the report plus the canonical
215	// swaps, so a later import can detect content conflicts. Version carries
216	// the full rule parameters used for the findings; it is nil only in
217	// archives written before rule versions existed, which are interpreted
218	// under the built-in rules.
219	type record struct {
220		ChainID     string          `json:"chainId"`
221		BlockHash   string          `json:"blockHash"`
222		BlockNumber int64           `json:"blockNumber"`
223		Swaps       []Swap          `json:"swaps"`
224		Findings    []ReportFinding `json:"findings"`
225		Version     *RuleVersion    `json:"version,omitempty"`
226	}
227	
228	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
229	
230	func (r record) ruleVersion() RuleVersion {
231		if r.Version != nil {
232			return *r.Version
233		}
234		return BuiltinVersion()
235	}
236	
237	func (r record) report() Report {
238		return Report{
239			ChainID:     r.ChainID,
240			BlockHash:   r.BlockHash,
241			BlockNumber: r.BlockNumber,
242			SwapCount:   len(r.Swaps),
243			Version:     r.ruleVersion(),
244			Findings:    r.Findings,
245		}
246	}
247	
248	const (
249		archiveFileName = "archive.json"
250		lockFileName    = "lock"
251	)
252	
253	type archiveData struct {
254		Records []record `json:"records"`
255		// Versions and EnabledVersion are absent in archives written before
256		// rule versions existed; such archives run the built-in rules.
257		Versions       []RuleVersion `json:"versions,omitempty"`
258		EnabledVersion string        `json:"enabledVersion,omitempty"`
259		// Suppressions and AlertRecords are absent in archives written before
260		// offline alerting existed; such archives simply have no registered
261		// conditions and no processing history.
262		Suppressions []Suppression      `json:"suppressions,omitempty"`
263		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
264		// Reviews is absent in archives written before manual reviews existed;
265		// every conclusion then behaves as unreviewed.
266		Reviews []ReviewObject `json:"reviews,omitempty"`
267	}
268	
269	func readArchive(dir string) (archiveData, error) {
270		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
271		if errors.Is(err, os.ErrNotExist) {
272			return archiveData{Records: []record{}}, nil
273		}
274		if err != nil {
275			return archiveData{}, err
276		}
277		var data archiveData
278		if err := json.Unmarshal(raw, &data); err != nil {
279			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
280		}
281		return data, nil
282	}
283	
284	// writeArchiveAtomic replaces the archive file in one rename, so a crash
285	// can only expose the previous or the next complete commit, never a half
286	// written file.
287	func writeArchiveAtomic(dir string, data archiveData) error {
288		raw, err := json.MarshalIndent(data, "", "  ")
289		if err != nil {
290			return err
291		}
292		tmp := filepath.Join(dir, archiveFileName+".tmp")
293		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
294		if err != nil {
295			return err
296		}
297		if _, err := f.Write(raw); err != nil {
298			f.Close()
299			os.Remove(tmp)
300			return err
301		}
302		if err := f.Sync(); err != nil {
303			f.Close()
304			os.Remove(tmp)
305			return err
306		}
307		if err := f.Close(); err != nil {
308			os.Remove(tmp)
309			return err
310		}
311		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
312			os.Remove(tmp)
313			return err
314		}
315		if d, err := os.Open(dir); err == nil {
316			d.Sync()
317			d.Close()
318		}
319		return nil
320	}
321	
322	// lockArchive takes an flock on the archive's lock file. The lock is
323	// released automatically if the process dies, so no stale locks survive.
324	func lockArchive(dir string, how int) (*os.File, error) {
325		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
326		if err != nil {
327			return nil, err
328		}
329		if err := syscall.Flock(int(f.Fd()), how); err != nil {
330			f.Close()
331			if errors.Is(err, syscall.EWOULDBLOCK) {
332				return nil, ErrBusy
333			}
334			return nil, err
335		}
336		return f, nil
337	}
338	
339	type parsedBlock struct {
340		line  int
341		block Block
342	}
343	
344	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
345		var out []parsedBlock
346		reader := bufio.NewReader(r)
347		lineNo := 0
348		for {
349			raw, err := reader.ReadBytes('\n')
350			if len(raw) > 0 {
351				lineNo++
352			}
353			if text := strings.TrimSpace(string(raw)); text != "" {
354				block, perr := parseBlock(text)
355				if perr != nil {
356					return nil, &LineError{Line: lineNo, Err: perr}
357				}
358				out = append(out, parsedBlock{line: lineNo, block: block})
359			}
360			if err == io.EOF {
361				return out, nil
362			}
363			if err != nil {
364				return nil, err
365			}
366		}
367	}
368	
369	// ReplayFile imports the line-delimited blocks in inputPath into the
370	// archive at dir and returns one report per distinct block, in order of
371	// first appearance. New blocks are judged under the archive's currently
372	// enabled rule version.
373	func ReplayFile(inputPath, dir string) ([]Report, error) {
374		return replayFile(inputPath, dir, "")
375	}
376	
377	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
378	// version instead of the archive's enabled one.
379	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
380		if versionID == "" {
381			return nil, errors.New("version id must not be empty")
382		}
383		return replayFile(inputPath, dir, versionID)
384	}
385	
386	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
387		f, err := os.Open(inputPath)
388		if err != nil {
389			return nil, err
390		}
391		defer f.Close()
392		return doReplay(f, dir, versionID)
393	}
394	
395	// Replay parses, validates and archives blocks from r under the archive's
396	// currently enabled rule version. Every line is checked before anything is
397	// written; any failure leaves the archive untouched. New reports are
398	// committed together in a single atomic write.
399	func Replay(input io.Reader, dir string) ([]Report, error) {
400		return doReplay(input, dir, "")
401	}
402	
403	// ReplayWithVersion is Replay under an explicitly registered rule version
404	// instead of the archive's enabled one.
405	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
406		if versionID == "" {
407			return nil, errors.New("version id must not be empty")
408		}
409		return doReplay(input, dir, versionID)
410	}
411	
412	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
413		parsed, err := parseBlocks(input)
414		if err != nil {
415			return nil, err
416		}
417	
418		// Collapse repeated identities within this file, keeping first
419		// appearance order; conflicting content rejects the whole file.
420		type occurrence struct {
421			block Block
422			line  int
423		}
424		order := []occurrence{}
425		firstSeen := make(map[blockID]int)
426		for _, p := range parsed {
427			id := blockID{p.block.ChainID, p.block.BlockHash}
428			if first, ok := firstSeen[id]; ok {
429				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
430					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
431						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
432				}
433				continue
434			}
435			firstSeen[id] = len(order)
436			order = append(order, occurrence{block: p.block, line: p.line})
437		}
438	
439		if err := os.MkdirAll(dir, 0o755); err != nil {
440			return nil, err
441		}
442		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
443		if err != nil {
444			return nil, err
445		}
446		defer lock.Close()
447	
448		data, err := readArchive(dir)
449		if err != nil {
450			return nil, err
451		}
452		// Resolve the version once, while the exclusive lock is held: every
453		// new block in this run is judged under the same rules even if another
454		// process enables a different version right after we finish.
455		version, err := resolveReplayVersion(data, versionID)
456		if err != nil {
457			return nil, err
458		}
459		archived := make(map[blockID]int, len(data.Records))
460		for i, rec := range data.Records {
461			archived[rec.id()] = i
462		}
463	
464		reports := make([]Report, 0, len(order))
465		changed := false
466		for _, occ := range order {
467			id := blockID{occ.block.ChainID, occ.block.BlockHash}
468			if idx, ok := archived[id]; ok {
469				rec := data.Records[idx]
470				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
471					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
472						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
473				}
474				// Identical re-import: return the original report, add nothing.
475				reports = append(reports, rec.report())
476				continue
477			}
478			rec := record{
479				ChainID:     occ.block.ChainID,
480				BlockHash:   occ.block.BlockHash,
481				BlockNumber: occ.block.BlockNumber,
482				Swaps:       occ.block.Swaps,
483				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
484				Version:     &version,
485			}
486			archived[id] = len(data.Records)
487			data.Records = append(data.Records, rec)
488			reports = append(reports, rec.report())
489			changed = true
490		}
491		if changed {
492			if err := writeArchiveAtomic(dir, data); err != nil {
493				return nil, err
494			}
495		}
496		return reports, nil
497	}
498	
499	// resolveReplayVersion picks the rule version for one replay run: the
500	// explicitly requested one, or the archive's currently enabled version.
501	func resolveReplayVersion(data archiveData, versionID string) (RuleVersion, error) {
502		if versionID != "" {
503			return findVersion(data, versionID)
504		}
505		return data.enabledVersion()
506	}
507	
508	// Query returns the archived report for one block identity. It only reads
509	// the archive; the original input file is not needed.
510	func Query(dir, chainID, blockHash string) (Report, error) {
511		if _, err := os.Stat(dir); err != nil {
512			if errors.Is(err, os.ErrNotExist) {
513				return Report{}, ErrUnknownBlock
514			}
515			return Report{}, err
516		}
517		lock, err := lockArchive(dir, syscall.LOCK_SH)
518		if err != nil {
519			return Report{}, err
520		}
521		defer lock.Close()
522	
523		data, err := readArchive(dir)
524		if err != nil {
525			return Report{}, err
526		}
527		for _, rec := range data.Records {
528			if rec.ChainID == chainID && rec.BlockHash == blockHash {
529				return rec.report(), nil
530			}
531		}
532		return Report{}, ErrUnknownBlock
533	}
