1	// Command mevwatch is the MEV 与链上风险监控系统 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"strings"
11	
12		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
13	)
14	
15	func main() {
16		command := "demo"
17		if len(os.Args) > 1 {
18			command = os.Args[1]
19		}
20		switch command {
21		case "demo":
22			runDemo()
23		case "version":
24			fmt.Println("mevwatch 0.1.0")
25		case "replay":
26			runReplay(os.Args[2:])
27		case "report":
28			if len(os.Args) != 5 {
29				fmt.Fprintln(os.Stderr, "usage: mevwatch report <archive-dir> <chainId> <blockHash>")
30				os.Exit(2)
31			}
32			report, err := mevwatch.Query(os.Args[2], os.Args[3], os.Args[4])
33			if err != nil {
34				fmt.Fprintf(os.Stderr, "report: %v\n", err)
35				os.Exit(1)
36			}
37			writeJSON(report)
38		case "rules":
39			runRules(os.Args[2:])
40		case "alerts":
41			runAlerts(os.Args[2:])
42		case "suppressions":
43			runSuppressions(os.Args[2:])
44		case "reviews":
45			runReviews(os.Args[2:])
46		case "compare":
47			if len(os.Args) != 6 {
48				fmt.Fprintln(os.Stderr, "usage: mevwatch compare <archive-dir> <chainId> <blockHash> <version-id>")
49				os.Exit(2)
50			}
51			result, err := mevwatch.Compare(os.Args[2], os.Args[3], os.Args[4], os.Args[5])
52			if err != nil {
53				fmt.Fprintf(os.Stderr, "compare: %v\n", err)
54				os.Exit(1)
55			}
56			writeJSON(result)
57		case "help", "-h", "--help":
58			usage()
59		default:
60			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
61			usage()
62			os.Exit(2)
63		}
64	}
65	
66	func usage() {
67		fmt.Println("usage: mevwatch [command]")
68		fmt.Println("  demo                                     run the built-in sandwich demo (default)")
69		fmt.Println("  version                                  print version")
70		fmt.Println("  replay [--version <id>] <input> <dir>    import line-delimited blocks into the archive")
71		fmt.Println("  report <archive-dir> <chainId> <hash>    print the archived block report")
72		fmt.Println("  rules list <archive-dir>                 list rule versions and the enabled one")
73		fmt.Println("  rules show <archive-dir> <version-id>    print one version's full parameters")
74		fmt.Println("  rules register <archive-dir> <spec-file> register a rule version ('-' reads stdin)")
75		fmt.Println("  rules enable <archive-dir> <version-id>  enable a registered version for later replays")
76		fmt.Println("  compare <archive-dir> <chainId> <hash> <version-id>")
77		fmt.Println("                                           re-judge an archived block under a version and diff")
78		fmt.Println("  alerts generate <archive-dir> <chainId> <startHeight> <endHeight> <minSeverity> <channel>")
79		fmt.Println("                                           generate offline alerts from archived conclusions")
80		fmt.Println("  alerts history <archive-dir> <chainId> <channel> <startHeight> <endHeight>")
